def target_location(is_active, is_focussed, index, hand_size):
  max_hand_size = 1600
  hand_width = math.min(max_hand_size, 240 * hand_size)
  centered_index = index - (hand_size - 1) / 2
  offset = (hand_width * centered_index) / (hand_size + 1)
  raise = is_active or is_focussed
  angle = (((hand_width / max_hand_size) * 0.6 * 180) / 3.1415) * math.atan(centered_index / hand_size)
  return {x: offset, y: 19 * ((hand_width / max_hand_size) * centered_index) ** 2 + (if raise { -180 } else { -65 }), a: angle}
def ease_to(from, to, delta, speed):
  dx = from.x - to.x
  dy = from.y - to.y
  dm = (dx ** 2 + dy ** 2) ** 0.5
  if dm <= speed * delta:
    return to
  else:
    return {x: from.x + ((to.x - from.x) * speed * delta) / dm, y: from.y + ((to.y - from.y) * speed * delta) / dm, a: 0}
```

