def get_extremes(possible_answers: List, category_index: Int):
  if possible_answers.len == 0:
    return {min: 0, max: 0}
  min = possible_answers[0].scores_delta[category_index]
  max = min
  i = 1
  while i < possible_answers.len:
    delta := possible_answers[i].scores_delta[category_index]
    if delta < min:
      min = delta
    if delta > max:
      max = delta
    i += 1
  return {min: min, max: max}
