def v2box_intersects_line(box: Box2, pin1: Point2, pin2: Point2) -> Bool:
  x1 := v2box_min_x(box)
  x2 := v2box_max_x(box)
  y1 := v2box_min_y(box)
  y2 := v2box_max_y(box)
  if not (pin1.x < x1 and pin2.x < x1) and not (pin1.x > x1 and pin2.x > x1):
    yp := seg_y_at_x(pin1, pin2, x1)
    if yp >= y1 and yp <= y2:
      return True
  if not (pin1.x < x2 and pin2.x < x2) and not (pin1.x > x2 and pin2.x > x2):
    yp := seg_y_at_x(pin1, pin2, x2)
    if yp >= y1 and yp <= y2:
      return True
  if not (pin1.y < y1 and pin2.y < y1) and not (pin1.y > y1 and pin2.y > y1):
    xp := seg_x_at_y(pin1, pin2, y1)
    if xp >= x1 and xp <= x2:
      return True
  if not (pin1.y < y2 and pin2.y < y2) and not (pin1.y > y2 and pin2.y > y2):
    xp := seg_x_at_y(pin1, pin2, y2)
    if xp >= x1 and xp <= x2:
      return True
  return False
```

